$('ask-thread')?.addEventListener('click',event=>{
  const btn=event.target?.closest?.('.ask-act');
  if(!btn)return;
  const turn=btn.closest('.ask-turn');
  const said=turn?.querySelector('.ask-said');
  const text=said?said.textContent:'';
  if(btn.dataset.act==='copy')copyAskText(text,btn);
  else if(btn.dataset.act==='regen')regenerateLastAsk();
  else if(btn.dataset.act==='edit')editLastUserAsk();
});
