  if(loggedIn){loadProviders();loadApiKeys();loadCreditsBalance()}
  else {creditBalanceCents=null;apiKeyCount=0;earnLoaded=false;earnTotalUsdc=null;earnTotalJobs=0;earnPending=[];earnRates=null;ownMacOnline=0;ownMacKnown=0;ownMacIds=new Set();ownMacModels=new Set();ownMacTps=0;preferSelf=false;preferSelfOff=false;clearProvideExpecting();paintCreditsBalance();paintEarn();paintAnswerApi();paintAskMyMac()}
  paintPayMethod();
